using System.Collections;using NUnit.Framework;using Rootborn.UI.Interiors;using UnityEngine;using UnityEngine.TestTools;using UnityEngine.UI;namespace Rootborn.Tests.PlayMode.Interiors{public sealed class HouseUtilityMenuVisibilityPlayModeTests{GameObject root;GameObject log,ency,panel;FurniturePlacementStyle2Skin skin;[UnitySetUp]public IEnumerator Setup(){root=new GameObject("UtilityVisibilityFixture",typeof(RectTransform),typeof(Canvas));log=Make("WorldStateLogButton");ency=Make("EncyclopediaButton");panel=Make("PlacementFixture");panel.SetActive(false);panel.AddComponent<InteriorFurniturePlacementPanel>();var s=Make("SkinFixture");skin=s.AddComponent<FurniturePlacementStyle2Skin>();yield return null;}GameObject Make(string n){var g=new GameObject(n,typeof(RectTransform));g.transform.SetParent(root.transform,false);return g;}[UnityTearDown]public IEnumerator Cleanup(){if(root!=null)Object.Destroy(root);yield return null;}[UnityTest]public IEnumerator PlacementTemporarilyHidesOwnedUtilitiesThenRestoresTheSameObjects(){yield return null;Assert.That(log!=null&&ency!=null,Is.True,"Placement styling must not destroy installed gameplay menus while closed");Assert.That(log.activeSelf&&ency.activeSelf,Is.True);panel.SetActive(true);yield return null;yield return null;Assert.That(log!=null&&ency!=null,Is.True);Assert.That(log.activeSelf||ency.activeSelf,Is.False,"Palette must remain unobscured");panel.SetActive(false);yield return null;yield return null;Assert.That(log.activeSelf&&ency.activeSelf,Is.True,"Closing placement must restore the original menu objects and their callbacks");}[UnityTest]public IEnumerator DisablingPlacementStylingRestoresOnlyControlsItTemporarilyHid(){ency.SetActive(false);panel.SetActive(true);yield return null;yield return null;Assert.That(log!=null,Is.True,"Menu must remain owned by its installer");Assert.That(log.activeSelf,Is.False);skin.enabled=false;Assert.That(log.activeSelf,Is.True);Assert.That(ency.activeSelf,Is.False,"A previously hidden control must not be enabled by the placement skin");}}}
